import json,re

def point_read(execute,key):
    if type(key) is not int or not 0<=key<8192:raise ValueError('approved point key required')
    plan=execute('EXPLAIN indexes=1 SELECT id FROM sparse WHERE id='+str(key)+' FORMAT JSONEachRow')
    lines=[json.loads(line)['explain'] for line in plan.splitlines() if line.strip()]
    match=re.search(r'Granules:\s*(\d+)/(\d+)','\n'.join(lines))
    if match is None:raise RuntimeError('native granule evidence missing')
    actual=json.loads(execute('SELECT id FROM sparse WHERE id='+str(key)+' SETTINGS optimize_move_to_prewhere=0 FORMAT JSON'))
    return {'ids':[row['id'] for row in actual['data']],'rows_read':actual['statistics']['rows_read'],'granules_selected':int(match[1]),'granules_total':int(match[2]),'exact_row_index_claimed':False}
